<?php require __DIR__.'/app/bootstrap.php'; ensure_v8_schema(); $slug=(string)($_GET['slug']??''); $post=cache_remember('public.article.'.hash('sha256',$slug), nowrd_cache_ttl('cache_ttl_article', 60), static function() use ($pdo,$slug) {$q=$pdo->prepare("SELECT p.*,u.name author_name FROM posts p LEFT JOIN users u ON u.id=p.author_id WHERE p.slug=? AND p.status='published' AND (p.published_at IS NULL OR p.published_at<=NOW()) LIMIT 1"); $q->execute([$slug]); return $q->fetch() ?: null;}); $sourceSlug=(string)($post['slug']??$slug); $lang=(string)($_GET['lang']??'id'); if(!in_array($lang,['id','en','es','fr','ja'],true))$lang='id';
$translation=null;
if($lang!=='id'){
 try{
  $pdo->exec("CREATE TABLE IF NOT EXISTS post_translations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, post_id INT UNSIGNED NOT NULL, language_code VARCHAR(5) NOT NULL, title VARCHAR(220) NOT NULL, slug VARCHAR(240) NOT NULL, excerpt TEXT NULL, seo_title VARCHAR(220) NULL, seo_description VARCHAR(320) NULL, content LONGTEXT NOT NULL, status ENUM('draft','published') NOT NULL DEFAULT 'draft', updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_post_translation(post_id,language_code), UNIQUE KEY uq_translation_slug(language_code,slug), INDEX idx_translation_language_status(language_code,status), CONSTRAINT fk_translation_post FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
  if(!$post){$tq=$pdo->prepare("SELECT p.*,u.name author_name FROM post_translations t JOIN posts p ON p.id=t.post_id LEFT JOIN users u ON u.id=p.author_id WHERE t.language_code=? AND t.slug=? AND t.status='published' AND p.status='published' AND (p.published_at IS NULL OR p.published_at<=NOW()) LIMIT 1");$tq->execute([$lang,$slug]);$post=$tq->fetch()?:null;if($post)$sourceSlug=(string)$post['slug'];}
  if($post){$tq=$pdo->prepare("SELECT * FROM post_translations WHERE post_id=? AND language_code=? AND status='published' LIMIT 1");$tq->execute([(int)$post['id'],$lang]);$translation=$tq->fetch()?:null;if($translation){foreach(['title','slug','excerpt','seo_title','seo_description','content'] as $field)$post[$field]=$translation[$field];}}
 }catch(Throwable $ex){error_log('NOWRD translation read failed: '.$ex->getMessage());}
}
if(!$post){http_response_code(404);} else { nowrd_track_page('article', (int)$post['id']); } $siteName=$config['site_name']??'NOWRD'; $postCats=$post?post_categories((int)$post['id']):[]; $postTags=$post?post_tags((int)$post['id']):[]; $related=[]; if($post && $postCats){ $catIds=array_map(static fn($c)=>(int)$c['id'],$postCats); $marks=implode(',',array_fill(0,count($catIds),'?')); $args=array_merge([(int)$post['id']],$catIds); $rq=$pdo->prepare("SELECT DISTINCT p.id,p.title,p.slug,p.excerpt,p.cover_image FROM posts p JOIN post_categories pc ON pc.post_id=p.id WHERE p.status='published' AND p.id<>? AND pc.category_id IN ($marks) AND (p.published_at IS NULL OR p.published_at<=NOW()) ORDER BY p.published_at DESC LIMIT 3"); $rq->execute($args); $related=$rq->fetchAll(); } $readingMinutes=$post?max(1,(int)ceil(str_word_count(strip_tags((string)$post['content']))/220)):1; ?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $post?e((($post['seo_title'] ?? '') ?: $post['title']).' — '.$siteName):'Story not found — NOWRD' ?></title><?php if($post): $seoDescription=trim((string)($post['seo_description'] ?? '')) ?: trim((string)($post['excerpt'] ?? '')); $canonical=trim((string)($post['canonical_url'] ?? '')) ?: base_url('article.php?slug='.rawurlencode($post['slug'])); $ogImage=(string)($post['cover_image'] ?? ''); ?><meta name="description" content="<?=e(text_substr($seoDescription,0,320))?>"><link rel="canonical" href="<?=e($canonical)?>"><meta property="og:type" content="article"><meta property="og:title" content="<?=e(($post['seo_title'] ?? '') ?: $post['title'])?>"><meta property="og:description" content="<?=e(text_substr($seoDescription,0,320))?>"><meta property="og:url" content="<?=e($canonical)?>"><?php if(valid_http_url($ogImage) && $ogImage!==''): ?><meta property="og:image" content="<?=e($ogImage)?>"><?php endif; ?><meta name="twitter:card" content="<?= $ogImage!=='' ? 'summary_large_image' : 'summary' ?>"><meta name="twitter:title" content="<?=e(($post['seo_title'] ?? '') ?: $post['title'])?>"><meta name="twitter:description" content="<?=e(text_substr($seoDescription,0,320))?>"><?php endif; ?><link rel="stylesheet" href="<?=e(base_url('public/assets/style.css'))?>"><style>.reading-progress{position:fixed;top:0;left:0;height:3px;width:0;background:var(--accent,#c6f36b);z-index:9999;transition:width .08s linear}.reading-time{font-size:12px;color:var(--muted)}.related-stories{margin:36px 0;padding-top:20px;border-top:1px solid var(--line)}.related-stories a{display:block;padding:14px;border:1px solid var(--line);border-radius:12px;margin:10px 0;color:var(--ink)}.article-taxonomy,.article-tags{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}.article-taxonomy a,.article-tags a{border:1px solid var(--line);border-radius:999px;padding:6px 10px;font-size:12px;color:var(--muted)}.article-taxonomy a{background:var(--accent);border-color:var(--accent);color:var(--ink)}.article-tags span{font-size:12px;color:var(--muted);padding:6px 0}</style></head><body><div class="reading-progress" id="readingProgress" aria-hidden="true"></div><header class="site-header wrap"><a class="brand" href="<?=e(base_url('index.php'))?>"><span class="brand-mark">n.</span> <?=e($siteName)?></a><nav><a href="<?=e(base_url('index.php'))?>">← All stories</a> &nbsp; <a href="<?=e(base_url('article.php?slug='.rawurlencode($sourceSlug).'&lang=id'))?>">ID</a> / <a href="<?=e(base_url('article.php?slug='.rawurlencode($sourceSlug).'&lang=en'))?>">EN</a></nav></header><main class="article wrap"><?php if(!$post): ?><div class="empty"><h2>Story not found.</h2><a class="button" href="<?=e(base_url('index.php'))?>">Back to journal</a></div><?php else: ?><div class="eyebrow"><span class="dot"></span> THE JOURNAL</div><h1><?=e($post['title'])?></h1><p class="article-deck"><?=e($post['excerpt'])?></p><div class="article-meta">By <?=e($post['author_name'] ?: $siteName)?> <span>·</span> <?=e(date('F j, Y',strtotime($post['published_at'] ?: $post['created_at'])))?> <span>·</span> <span class="reading-time"><?=$readingMinutes?> min read</span></div><?php if($postCats):?><div class="article-taxonomy"><?php foreach($postCats as $cat):?><a href="<?=e(base_url('index.php?category='.rawurlencode($cat['slug']).'#latest'))?>"><?=e($cat['name'])?></a><?php endforeach;?></div><?php endif;?><?php if($post['cover_image'] && valid_http_url($post['cover_image'])): ?><img class="article-cover" src="<?=e($post['cover_image'])?>" alt="Cover image"><?php endif; ?><div class="article-content"><?=render_rich_html((string)$post['content'])?></div><?php if($related):?><section class="related-stories"><h2>Related stories</h2><?php foreach($related as $rp):?><a href="<?=e(base_url('article.php?slug='.rawurlencode($rp['slug'])))?>"><strong><?=e($rp['title'])?></strong><?php if($rp['excerpt']):?><p><?=e(text_substr($rp['excerpt'],0,140))?></p><?php endif;?></a><?php endforeach;?></section><?php endif;?><?php if($postTags):?><div class="article-tags"><span>Tags</span><?php foreach($postTags as $tag):?><a href="<?=e(base_url('index.php?q='.rawurlencode($tag['name']).'#latest'))?>">#<?=e($tag['name'])?></a><?php endforeach;?></div><?php endif;?><a class="back-link" href="<?=e(base_url('index.php'))?>">← Back to all stories</a><?php endif; ?></main><footer class="footer wrap"><a class="brand" href="<?=e(base_url('index.php'))?>"><span class="brand-mark">n.</span> NOWRD</a><span>© <?=date('Y')?> NOWRD Studio</span></footer><script>window.NOWRD_VISUAL = <?=json_encode(nowrd_visual_preferences(), JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>; window.NOWRD_VISUAL_ADMIN = false;</script><script>(()=>{const bar=document.getElementById('readingProgress');if(!bar)return;const update=()=>{const d=document.documentElement;const max=d.scrollHeight-d.clientHeight;bar.style.width=(max>0?Math.min(100,Math.max(0,d.scrollTop/max*100)):0)+'%'};window.addEventListener('scroll',update,{passive:true});window.addEventListener('resize',update);update()})();</script><script src="<?=e(base_url('public/assets/ui-v10.js'))?>" defer></script></body></html>
